functions.teams_module_session_limit:
def teams_module_session_limit(module_catalogue_id):
    """Legacy calendars keep52; stored study weeks permit their bounded1-7 days.

    The request cannot opt itself into a larger limit: only the saved module's
    creation-time layout and authored week count provide that entitlement.
    """
    module = authoring_module_exists(module_catalogue_id) if module_catalogue_id else None
    if module and module_week_boundary_mode(module) == 'calendar':
        return max(52, min(104, module_stored_week_count(module)) * 7)
    return 52

functions.delivery_days_per_week:
def delivery_days_per_week(module_row):
    """How many days a week this module delivers on, from its stored delivery day.

    A group can run the same module on more than one day (e.g. Mon + Thu), so
    the calendar session count is the authored week count times this. Never
    below 1: a module with no delivery day still runs once per week.
    """
    weekly = module_weekly_schedule(module_row)
    if weekly:
        return len(weekly)
    raw = clean_str((module_row or {}).get('session_week_day') or (module_row or {}).get('weekDays'))
    if not raw:
        return 1
    return max(1, len([part for part in (piece.strip() for piece in raw.split(',')) if part]))

functions.curriculum_preview_module_session_plan:
def curriculum_preview_module_session_plan(request):
    if request.method != 'POST':
        return json_error('Method not allowed.', status=405)
    payload = json_body(request)
    if payload is None:
        return json_error('Invalid JSON body.')
    try:
        module_week_starts_on(payload)
        if module_week_boundary_mode(payload) and not module_week_starts_on(payload):
            raise ValueError("Choose the first day of the study week.")
    except ValueError as exc:
        return json_error(str(exc), fields=['weekStartsOn'])
    try:
        weekly = module_weekly_schedule(payload)
    except ValueError as exc:
        return json_error(str(exc), fields=['weeklySchedule'])
    if module_week_boundary_mode(payload) or (payload.get('endDate') and payload.get('weeksNumber')):
        slot = {**module_schedule_view(payload), 'schedule_mode': payload.get('scheduleMode') or 'custom'}
        try:
            return JsonResponse(module_delivery_session_plan(slot, 0, parse_date(payload.get('startDate')), payload.get('holidays') or [], week_count=parse_int(payload.get('weeksNumber'), 0)))
        except ValueError as exc:
            return json_error(str(exc), fields=['weeksNumber', 'endDate'])
    plan = build_module_session_plan(
        payload.get('startDate') or payload.get('start_date'),
        payload.get('numberOfSessions') or payload.get('sessionsNumber') or payload.get('weeks'),
        ', '.join(slot['day'] for slot in weekly) or payload.get('deliveryDays') or payload.get('weekDays') or payload.get('delivery_day'),
        payload.get('holidays') or payload.get('linkedHolidays') or [],
        week_count=parse_int(payload.get('weeksNumber'), 0),
        week_starts_on=first_weekly_session_day(payload.get('startDate'), weekly)
        if payload.get('scheduleMode') == 'custom' and len(weekly) > 1 and module_week_starts_on(payload) else None,
    )
    slot = module_schedule_view(payload)
    for session in plan.get('sessions') or []:
        clock, end, duration = module_session_clock(slot, session_date=session.get('date'))
        session.update(startTime=clock, endTime=end, durationMinutes=duration)
    return JsonResponse(plan)

functions.curriculum_module_session_plan:
def curriculum_module_session_plan(request, module_catalogue_id):
    """The flat session dates for a module week count that is not saved yet.

    Module Builder adds and removes weeks before anything is written, and
    authored week N is calendar week N of the module's own run -- so a seventh
    week added to a six-week module has to be given the seventh Monday-to-Sunday
    window's delivery days. Asking here is what keeps those dates identical to
    the ones the structure payload serves after the save, instead of the browser
    deriving a schedule of its own that then disagrees with the calendar and the
    Teams series.

    ``?weeks=`` is the authored week count, and the plan runs to the end of that
    many Mon-Sun windows -- however many delivery days the group actually has in
    them, which is not the same number for a module that starts mid-week.
    ``?sessions=`` remains available for callers with a raw count of dates.
    """
    if request.method != 'GET':
        return json_error('Method not allowed.', status=405)
    try:
        catalogue_id = resolve_stored_module_catalogue_id(module_catalogue_id)
        module_rows = authoring_fetch_all(
            AUTHORING_MODULES_TABLE, 'module_catalogue_id = %s', [catalogue_id],
        ) if catalogue_id else []
        if not module_rows:
            # An unsaved draft has no stored schedule to plan from, and answering
            # with an empty plan would read as "these weeks have no dates".
            return json_error('Module not found.', status=404)
        module_row = module_rows[0]
        if module_row.get('group_id'):
            # The group's day and clock, which govern every module delivered to
            # it; the module's own answer only where the group states none.
            module_row = module_delivery_row(module_row, fetch_group_row(module_row['group_id']) or {})
        requested_sessions = max(0, parse_int(request.GET.get('sessions'), 0))
        requested_weeks = max(0, parse_int(request.GET.get('weeks'), 0))
        if module_week_boundary_mode(module_row) and requested_weeks > 104:
            return json_error('Choose between 1 and 104 study weeks.', fields=['weeks'])
        if requested_sessions:
            plan = module_session_plan_for_count(module_row, requested_sessions)
        else:
            plan = module_session_plan_for_weeks(
                module_row,
                requested_weeks or module_stored_week_count(module_row),
            )
    except Exception:
        logger.exception('Unable to plan module session dates for %s.', module_catalogue_id)
        return json_error('Unable to plan module session dates.', status=500)
    return JsonResponse({
        **plan,
        'moduleCatalogueId': catalogue_id,
        # Calendar plans carry the study-week windows the builder reads. Keep
        # the numeric count only for legacy plans that do not contain them.
        'weeks': plan.get('weeks', requested_weeks or module_stored_week_count(module_row)),
        'startDate': format_date(module_row.get('start_date')),
        'weekDays': clean_str(module_row.get('session_week_day')),
    })
